CREATE TABLE "project_risks" (
  "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "projectId" integer NOT NULL REFERENCES "projects"("id"),
  "title" varchar(180) NOT NULL,
  "description" text NOT NULL,
  "probability" integer NOT NULL CHECK ("probability" BETWEEN 1 AND 5),
  "impact" integer NOT NULL CHECK ("impact" BETWEEN 1 AND 5),
  "responsePlan" text,
  "responsible" varchar(160),
  "status" varchar(32) NOT NULL DEFAULT 'aberto',
  "createdBy" integer REFERENCES "users"("id"),
  "createdAt" timestamp with time zone NOT NULL DEFAULT now(),
  "updatedAt" timestamp with time zone NOT NULL DEFAULT now()
);
--> statement-breakpoint
CREATE INDEX "project_risks_project_idx" ON "project_risks"("projectId");
--> statement-breakpoint
CREATE TRIGGER "trg_project_risks_updated_at"
  BEFORE UPDATE ON "project_risks"
  FOR EACH ROW EXECUTE FUNCTION "set_updated_at"();
